import{mountShell}from'../shared/shell.js?v=0.7.0';import{attachCardDrag}from'../shared/drag.js?v=0.7.0';import{readStore,writeStore,downloadText}from'../shared/utils.js?v=0.7.0';import{create,validate,swap,evaluate,compare}from'./engine.js?v=0.7.0';mountShell({active:'accuracy'});const app=document.querySelector('#app'),KEY='thinking-lab:accuracy:v1';let stored=readStore(KEY,null),s,baseline,past=[],destroy=()=>{},message='';try{s=validate(stored?.s||create());baseline=stored?.baseline?validate(stored.baseline):null;}catch{s=create();baseline=null;}const f=x=>x.toFixed(1),sign=x=>x>0?'+'+x:String(x);function save(){if(!writeStore(KEY,{s,baseline}))message='Storage unavailable. Export to keep this experiment.';}function change(next,text){past.push({s:structuredClone(s),baseline:structuredClone(baseline)});past=past.slice(-40);s=validate(next);message=text;save();render();}function render(){destroy();const r=evaluate(s),b=compare(s,baseline);app.innerHTML=`<section class="surface"><div class="toolbar"><button id="pin">Pin this allocation</button><button id="undo" ${!past.length?'disabled':''}>Undo</button><button id="reset">Reset</button><span class="hint">Drag an error onto another moment to swap them. Or use its Swap selector.</span></div><p class="status" role="status">${message||'Act when the forecast meets the threshold. Above-threshold actual values are opportunities worth acting on.'}</p><div class="accuracy-board">${r.rows.map((row,i)=>`<section class="moment ${row.kind}" data-drop-id="${i}"><h2>Moment ${i+1}</h2><div class="bars" role="img" aria-label="Actual ${row.actual}, forecast ${row.forecast}, threshold ${s.threshold}"><i class="threshold" style="bottom:${s.threshold/120*100}%"></i><div class="bar actual" style="height:${row.actual/120*100}%"><span>${row.actual}</span></div><div class="bar forecast" style="height:${row.forecast/120*100}%"><span>${row.forecast}</span></div></div><div class="error-tile" data-drag-id="${i}"><button data-drag-handle aria-label="Drag error ${sign(row.error)} at moment ${i+1}">${sign(row.error)}<small>error</small></button><label for="swap-${i}">Swap with</label><select id="swap-${i}" data-swap="${i}"><option value="">Choose…</option>${r.rows.map((_,j)=>j!==i?`<option value="${j}">Moment ${j+1}</option>`:'').join('')}</select></div><strong class="decision">${row.act?'Act':'Wait'}</strong><span>${row.kind==='miss'?'Missed opportunity':row.kind==='falseAlarm'?'Unnecessary action':'Right decision'}</span><b>Loss ${row.cost}</b></section>`).join('')}</div><p class="hint">Left bars: actual values. Right bars: forecasts. Dashed line: decision threshold. The error tiles form a fixed budget; swaps preserve both MAE and RMSE.</p></section><section class="metrics"><div class="metric"><span>Mean absolute error</span><strong>${f(r.mae)}</strong><small>${b?`${f(b.mae)} pinned`:'Average size of the error'}</small></div><div class="metric"><span>Root mean squared error</span><strong>${f(r.rmse)}</strong><small>${b?`${f(b.rmse)} pinned`:'More weight on large errors'}</small></div><div class="metric"><span>Total decision loss</span><strong>${r.loss}</strong><small>${b?`${b.loss} pinned · ${sign(r.loss-b.loss)} difference`:'Illustrative loss units'}</small></div><div class="metric"><span>Wrong decisions</span><strong>${r.misses+r.falseAlarms}/8</strong><small>${r.misses} missed · ${r.falseAlarms} unnecessary</small></div></section><div class="split"><section class="surface"><h2>What makes an error matter?</h2><div class="fields">${[['threshold','Act at or above',20,100],['miss','Loss from missing an opportunity',0,20],['falseAlarm','Loss from unnecessary action',0,20]].map(([k,l,min,max])=>`<div class="field"><label for="${k}">${l} <output>${s[k]}</output></label><input id="${k}" data-param="${k}" type="range" min="${min}" max="${max}" value="${s[k]}"></div>`).join('')}</div><p>Both allocations use these same decision rules. Moving an error far from the threshold can make it irrelevant to the action.</p></section><section class="surface"><h2>Reference decisions</h2><table><tr><th>Rule</th><th>Loss</th></tr><tr><td>This forecast allocation</td><td>${r.loss}</td></tr><tr><td>Always act</td><td>${r.alwaysAct}</td></tr><tr><td>Never act</td><td>${r.neverAct}</td></tr><tr><td>See actual values before acting</td><td>0 (unavailable ideal)</td></tr></table><p class="hint">The constant rules need no forecast. The ideal has information unavailable when a decision is made.</p></section></div><details><summary>Change the situation’s actual values</summary><p>Values can range from 20 to 100. Forecast errors stay fixed; pinned allocations share these edits.</p><div class="actual-inputs">${s.actual.map((v,i)=>`<label for="actual-${i}">Moment ${i+1}<input id="actual-${i}" data-actual="${i}" type="number" min="20" max="100" value="${v}"></label>`).join('')}</div></details><details><summary>Mechanism and limits</summary><p>Forecast = actual + the assigned error. Act if forecast ≥ threshold. A missed above-threshold opportunity incurs the miss loss; acting below the threshold incurs the unnecessary-action loss. Correct decisions have zero loss. MAE averages absolute errors; RMSE is the square root of their mean square.</p><p>These are eight independent, fictional decisions. Fixed error rearrangements reveal how location and asymmetry matter; they do not simulate a trainable forecasting model. There is no budget, inventory, serial correlation, asset valuation or financial calibration. Tuning an allocation after seeing actuals is hindsight exploration, not a deployable forecasting policy.</p></details><p class="local-note">Your settings and pinned allocation save in this browser.</p>`;bind();destroy=attachCardDrag({root:app,onDrop:({itemId,dropId})=>{if(itemId!==dropId)change(swap(s,+itemId,+dropId),'Errors swapped. Accuracy is unchanged; inspect the decisions.');}});}function bind(){app.querySelectorAll('[data-swap]').forEach(el=>el.onchange=()=>{if(el.value!=='')change(swap(s,+el.dataset.swap,+el.value),'Errors swapped.');});app.querySelectorAll('[data-param]').forEach(el=>el.onchange=()=>change({...s,[el.dataset.param]:+el.value},'The decision rule changed for both allocations.'));app.querySelectorAll('[data-actual]').forEach(el=>el.onchange=()=>{if(!el.checkValidity()||el.value===''){el.reportValidity();return;}const n=structuredClone(s);n.actual[+el.dataset.actual]=+el.value;change(n,'Actual values changed in both allocations.');});document.querySelector('#pin').onclick=()=>{past.push({s:structuredClone(s),baseline:structuredClone(baseline)});baseline=structuredClone(s);message='Allocation pinned. Move the same errors to compare.';save();render();};document.querySelector('#undo').onclick=()=>{const p=past.pop();if(p){s=p.s;baseline=p.baseline;save();render();}};document.querySelector('#reset').onclick=()=>change(create(),'Initial situation restored.');}document.querySelector('#export').onclick=()=>downloadText('accuracy-and-decisions.md',`# Accurate enough for which decision?\n\nEight fictional independent decisions; rearranging known errors is a hindsight experiment.\n\nMAE: ${f(evaluate(s).mae)}. RMSE: ${f(evaluate(s).rmse)}. Decision loss: ${evaluate(s).loss}.\n\n\`\`\`json\n${JSON.stringify({settings:s,baseline,result:evaluate(s),comparison:compare(s,baseline)},null,2)}\n\`\`\`\n`.replaceAll('\n','\n'),'text/markdown');render();
